def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opps = []
    prev_bids = []
    strong_prev = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if opp.get('budget', 0) > 0:
                    strong_prev.append(bid)

    if not alive_opps:
        return min(budget, 18.0)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_strong = sum(strong_prev) / len(strong_prev) if strong_prev else highest_prev

    tight_supply = supply <= 17
    medium_supply = supply <= 20
    critical_hp = hp <= 3 or no_water_days >= 2
    pressured_hp = hp <= 5 or no_water_days >= 1

    bid = 0.0

    if critical_hp:
        bid = max(0.92 * DAILY_SALARY, highest_prev + 2.0)
    elif tight_supply:
        bid = max(0.78 * DAILY_SALARY, min(highest_prev + 1.5, 0.95 * DAILY_SALARY))
    elif medium_supply:
        if avg_strong >= 120:
            bid = 22.0
        else:
            bid = max(28.0, min(avg_strong * 0.45, 0.62 * DAILY_SALARY))
    else:
        if pressured_hp:
            bid = max(26.0, min(highest_prev * 0.35, 0.55 * DAILY_SALARY))
        else:
            bid = 12.0

    if budget < bid:
        if critical_hp:
            return max(0.0, budget)
        bid = min(budget, max(0.0, bid))

    reserve = 0.0
    if hp > 6:
        reserve = 35.0
    elif hp > 4:
        reserve = 20.0

    if not critical_hp and budget - bid < reserve:
        bid = max(0.0, budget - reserve)

    if pressured_hp and bid < 18.0 and budget >= 18.0:
        bid = 18.0

    if tight_supply and bid < 40.0 and not critical_hp and budget >= 40.0:
        bid = 40.0

    return min(budget, max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive = len(alive_opponents) + 1

    # Calculate fair share based on supply
    fair_share_price = (DAILY_SALARY * 1.1) if supply < (num_alive * WATER_REQ) else (DAILY_SALARY * 0.6)

    # Look at yesterday's bids to gauge aggression
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev:
            yesterday_bids.append(prev['bid'])

    bid = fair_share_price
    if yesterday_bids:
        max_prev = max(yesterday_bids)
        # If supply is tight, match or slightly exceed top competitor
        if supply < (num_alive * WATER_REQ):
            bid = max(fair_share_price, max_prev * 1.05)
        else:
            bid = max(fair_share_price, max_prev * 0.8)

    # Desperation mode
    if my_status['hp'] <= 3:
        bid = min(my_status['budget'], DAILY_SALARY * 1.5)

    return float(min(my_status['budget'], bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.3)

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine base bid from yesterday's maximum
    if yesterday_bids:
        yesterday_max = max(yesterday_bids)
    else:
        yesterday_max = 0

    # Urgency based on HP and no_water_days
    need_water = (hp <= 2) or (no_water_days >= 1)

    if need_water:
        # Must secure water: bid just above yesterday's max if affordable
        target = min(budget, max(1, yesterday_max + 0.5))
        # But not exceed a reasonable fraction of salary
        target = min(target, DAILY_SALARY * 0.9)
    else:
        # Conservative: try to save, bid low
        target = min(budget, DAILY_SALARY * 0.4)
        # If yesterday's max was high, we might need to bid a bit more to avoid losing often
        if yesterday_max > DAILY_SALARY * 0.7:
            target = min(budget, DAILY_SALARY * 0.55)

    # Ensure non-negative and integer-like (float is fine)
    return max(0.0, target)
